"use client";
import React, { useState } from "react";
import reactElementToJSXString from "react-element-to-jsx-string";
import { toast } from "sonner";
import { AnimateText } from "@/registry/ui/animated-text";
import { Copy, Check } from "lucide-react";

interface AnimationCard {
  children: React.ReactNode;
  onClick: () => void;
  isCopied: boolean;
  title: string;
}

type AnimatedTextType = {
  name: string;
  description: string;
  component: React.ReactNode;
  code?: string;
};

const AnimationCard = ({
  children,
  onClick,
  isCopied,
  title,
}: AnimationCard) => {
  return (
    <div
      className="border group relative rounded-lg p-3 sm:p-4 transition-shadow duration-300 cursor-pointer bg-background"
      onClick={onClick}
    >
      <p className="text-xs sm:text-sm font-semibold mb-2">{title}</p>
      <div className="overflow-hidden">{children}</div>
      <div className="absolute top-2 right-2">
        {isCopied ? (
          <Check className="h-3 w-3 text-green-500 transition-all duration-200" />
        ) : (
          <Copy className="h-3 w-3 text-zinc-300 dark:text-zinc-700 group-hover:text-zinc-500 group-hover:dark:text-zinc-500" />
        )}
      </div>
    </div>
  );
};

export const AnimationTextDemo = () => {
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);

  const copy = (animation: AnimatedTextType, index: number) => {
    if (animation.code) {
      copyToClipboard(animation.code, index);
      return;
    }
    let animationString = reactElementToJSXString(animation.component, {
      displayName: (element) => {
        if (
          typeof element === "object" &&
          element !== null &&
          "type" in element &&
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          (element as any).type?.name === "AnimateText"
        ) {
          return "AnimateText";
        }
        if (
          typeof element === "object" &&
          element !== null &&
          "type" in element &&
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          (element as any).type?.name
        ) {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          return (element as any).type.name;
        }
        return "UnknownComponent";
      },
      functionValue: (fn) => fn.name || "function",
    });

    if (animationString) {
      const textToCopy = animationString;
      copyToClipboard(textToCopy, index);
    }
  };

  const copyToClipboard = (text: string, index: number) => {
    navigator.clipboard
      .writeText(text)
      .then(() => {
        console.log("Text copied to clipboard:", text);
        toast.success("Copied to clipboard");
        setCopiedIndex(index);
        setTimeout(() => {
          setCopiedIndex(null);
        }, 2000);
      })
      .catch((err) => {
        console.error("Error copying text to clipboard:", err);
        toast.error("Error copying to clipboard");
      });
  };

  return (
    <div className="w-full px-4 sm:px-6 md:px-8 max-w-7xl mx-auto py-6">
      <div className="flex flex-col">
        <div className="flex flex-col py-2 sm:py-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
            {animatedTextComponents.map((animation, idx) => (
              <AnimationCard
                key={idx}
                onClick={() => copy(animation, idx)}
                isCopied={copiedIndex === idx}
                title={animation.name}
              >
                {animation.component}
              </AnimationCard>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export const animatedTextComponents = [
  {
    name: "Cascade",
    description: "Text animation with cascade effect",
    component: <AnimateText text="Cascade" type="cascade" />,
    code: `<AnimateText text="Cascade" type="cascade" />`,
  },
  {
    name: "Flicker",
    description: "Text animation with flicker effect",
    component: <AnimateText text="Flicker" type="flicker" />,
    code: `<AnimateText text="Flicker" type="flicker" />`,
  },
  {
    name: "Blink",
    description: "Text animation with blink effect",
    component: <AnimateText text="Blink" type="blink" custom={1} />,
    code: `<AnimateText text="Blink" type="blink" custom={1} />`,
  },
  {
    name: "Expand",
    description: "Text animation with expand effect",
    component: <AnimateText text="Expand" type="expand" />,
    code: `<AnimateText text="Expand" type="expand" />`,
  },
  {
    name: "Rise",
    description: "Text animation with rise effect",
    component: <AnimateText text="Rise" type="rise" />,
    code: `<AnimateText text="Rise" type="rise" />`,
  },
  {
    name: "Glide",
    description: "Text animation with glide effect",
    component: <AnimateText text="Glide" type="glide" custom={1} />,
    code: `<AnimateText text="Glide" type="glide" custom={1} />`,
  },
  {
    name: "Elastic",
    description: "Text animation with elastic effect",
    component: <AnimateText text="Elastic" type="elastic" custom={1} />,
    code: `<AnimateText text="Elastic" type="elastic" custom={1} />`,
  },
  {
    name: "Float",
    description: "Text animation with float effect",
    component: <AnimateText text="Float" type="float" custom={1} />,
    code: `<AnimateText text="Float" type="float" custom={1} />`,
  },
];

"use client";

import { FC, useRef, useEffect } from "react";
import { HTMLMotionProps, motion, useAnimation, useInView } from "motion/react";

type AnimationType =
  | "blink"
  | "rise"
  | "expand"
  | "glide"
  | "cascade"
  | "flicker"
  | "elastic"
  | "float";

interface Props extends HTMLMotionProps<"div"> {
  text: string;
  type?: AnimationType;
  delay?: number;
  duration?: number;
  custom?: number;
}

const animationVariants = {
  blink: {
    container: {
      hidden: { opacity: 0 },
      visible: (i: number = 1) => ({
        opacity: 1,
        transition: { staggerChildren: 0.05, delayChildren: i * 0.3 },
      }),
    },
    child: {
      visible: {
        opacity: 1,
        y: 0,
        transition: {
          type: "spring",
          damping: 12,
          stiffness: 100,
          y: {
            type: "keyframes",
            times: [0, 0.5, 1],
            values: [0, -10, 0],
          },
        },
      },
      hidden: { opacity: 0, y: 10 },
    },
  },
  rise: {
    container: {
      hidden: { opacity: 0 },
      visible: {
        opacity: 1,
        transition: { staggerChildren: 0.1, delayChildren: 0.2 },
      },
    },
    child: {
      visible: { opacity: 1, y: 0, transition: { duration: 0.5 } },
      hidden: { opacity: 0, y: 20 },
    },
  },
  expand: {
    container: {
      hidden: { opacity: 0, scale: 0.8 },
      visible: {
        opacity: 1,
        scale: 1,
        transition: { staggerChildren: 0.05, delayChildren: 0.2 },
      },
    },
    child: {
      visible: {
        opacity: 1,
        scale: 1,
        transition: {
          type: "spring",
          damping: 15,
          stiffness: 400,
          scale: {
            type: "keyframes",
            times: [0, 0.6, 1],
            values: [0, 1.1, 1],
          },
        },
      },
      hidden: { opacity: 0, scale: 0 },
    },
  },
  float: {
    container: {
      hidden: {},
      visible: (i: number = 1) => ({
        transition: { staggerChildren: 0.03, delayChildren: 0.2 * i },
      }),
    },
    child: {
      hidden: {
        y: 50,
        opacity: 0,
      },
      visible: {
        y: 0,
        opacity: 1,
        transition: {
          duration: 0.5,
          ease: "easeOut",
        },
      },
    },
  },
  glide: {
    container: {
      hidden: {},
      visible: (i: number = 1) => ({
        transition: { staggerChildren: 0.03, delayChildren: 0.2 * i },
      }),
    },
    child: {
      hidden: {
        y: 20,
        opacity: 0,
      },
      visible: {
        y: 0,
        opacity: 1,
        transition: {
          duration: 0.5,
          ease: [0.22, 1, 0.36, 1],
        },
      },
    },
  },
  elastic: {
    container: {
      hidden: {},
      visible: (i: number = 1) => ({
        transition: { staggerChildren: 0.03, delayChildren: 0.2 * i },
      }),
    },
    child: {
      hidden: {
        y: 50,
        opacity: 0,
      },
      visible: {
        y: 0,
        opacity: 1,
        transition: {
          type: "spring",
          stiffness: 400,
          damping: 10,
        },
      },
    },
  },
  cascade: {
    container: {
      hidden: {},
      visible: {},
    },
    child: {
      hidden: {
        opacity: 0,
        y: `0.25em`,
      },
      visible: {
        opacity: 1,
        y: `0em`,
        transition: {
          duration: 0.65,
          ease: [0.65, 0, 0.75, 1],
        },
      },
    },
  },
  flicker: {
    container: {
      hidden: {},
      visible: {},
    },
    child: {
      hidden: {
        opacity: 0,
        y: `0.35em`,
      },
      visible: {
        opacity: 1,
        y: `0em`,
        transition: {
          duration: 0.45,
          ease: [0.85, 0.1, 0.9, 1.2],
        },
      },
    },
  },
};

export const AnimateText: FC<Props> = ({
  text,
  type = "elastic",
  custom = 1,
  className = "",
  ...props
}: Props) => {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: false });
  const ctrls = useAnimation();

  useEffect(() => {
    if (isInView) {
      ctrls.start("visible");
    } else {
      ctrls.start("hidden");
    }
  }, [isInView, ctrls]);

  const letters = Array.from(text);
  const { container, child } = animationVariants[type];

  if (type === "cascade" || type === "flicker") {
    return (
      <h2
        ref={ref}
        className={`mt-6 text-3xl font-bold text-black dark:text-neutral-100 py-4 px-4 md:text-4xl ${className}`}
      >
        {text.split(" ").map((word, index) => {
          return (
            <motion.span
              className="inline-block mr-[0.25em] whitespace-nowrap"
              aria-hidden="true"
              key={index}
              initial="hidden"
              animate={isInView ? "visible" : "hidden"}
              variants={container}
              transition={{
                delayChildren: index * 0.13,
                staggerChildren: 0.025,
              }}
            >
              {word.split("").map((character, index) => {
                return (
                  <motion.span
                    aria-hidden="true"
                    key={index}
                    variants={child}
                    className="inline-block -mr-[0.01em]"
                  >
                    {character}
                  </motion.span>
                );
              })}
            </motion.span>
          );
        })}
      </h2>
    );
  }

  return (
    <motion.h2
      ref={ref}
      style={{ display: "flex", overflow: "hidden" }}
      role="heading"
      variants={container}
      initial="hidden"
      animate={ctrls}
      custom={custom}
      className={`mt-6 text-3xl font-bold text-black dark:text-neutral-100 py-4 px-4 md:text-4xl ${className}`}
      {...props}
    >
      {letters.map((letter, index) => (
        <motion.span key={index} variants={child}>
          {letter === " " ? "\u00A0" : letter}
        </motion.span>
      ))}
    </motion.h2>
  );
};
